import java.util.*;

public class Main {
    static final int MAXN = 25;
    static final int MAXE = 400005;
    static final int INF = 1000000007;
    static final int SOURCE = 501;
    static final int SINK = 502;

    static char[][] firstGrid = new char[MAXN + 1][MAXN + 1];
    static char[][] secondGrid = new char[MAXN + 1][MAXN + 1];
    static int[][] distSafe = new int[MAXN + 1][MAXN + 1];
    static int[][][][] distBetween = new int[MAXN + 1][MAXN + 1][MAXN + 1][MAXN + 1];
    static int[] dirX = {-1, 1, 0, 0};
    static int[] dirY = {0, 0, -1, 1};

    static class Edge {
        int u, v, fl, c, nxt;
        Edge(int u, int v, int fl, int c, int nxt) {
            this.u = u;
            this.v = v;
            this.fl = fl;
            this.c = c;
            this.nxt = nxt;
        }
    }

    static Edge[] edges = new Edge[MAXE + 1];
    static int edgeCnt = 0;
    static int[] head = new int[505];
    static int[] parentEdge = new int[505];
    static int[] used = new int[505];
    static int depth = new int[505];
    static int answer = 0;

    static void addEdge(int u, int v, int cap) {
        edges[++edgeCnt] = new Edge(u, v, 0, cap, head[u]);
        head[u] = edgeCnt;
        edges[++edgeCnt] = new Edge(v, u, 0, 0, head[v]);
        head[v] = edgeCnt;
    }

    static boolean findPath() {
        Queue<Integer> qu = new LinkedList<>();
        Arrays.fill(used, 0);
        Arrays.fill(depth, 0);
        qu.add(SOURCE);
        used[SOURCE] = 1;
        depth[SOURCE] = 1;
        while (!qu.isEmpty()) {
            int x = qu.poll();
            for (int i = head[x]; i != 0; i = edges[i].nxt) {
                int y = edges[i].v;
                if (used[y] == 0 && edges[i].fl < edges[i].c) {
                    parentEdge[y] = i;
                    used[y] = 1;
                    depth[y] = depth[x] + 1;
                    qu.add(y);
                    if (y == SINK) return true;
                }
            }
        }
        return false;
    }

    static int sendFlow(int x, int now) {
        if (x == SINK || now == 0) return now;
        int remain = now;
        for (int i = head[x]; i != 0; i = edges[i].nxt) {
            if (edges[i].c > edges[i].fl && depth[edges[i].v] == depth[x] + 1) {
            int pushed = sendFlow(edges[i].v, Math.min(remain, edges[i].c - edges[i].fl));
            if (pushed == 0) depth[edges[i].v] = 0;
            edges[i].fl += pushed;
            edges[((i - 1) ^ 1) + 1].fl -= pushed;
            remain -= pushed;
            if (remain == 0) break;
        }
    }
    return now - remain;
}

static void runDinic() {
    while (findPath()) answer += sendFlow(SOURCE, INF);
}

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int limit = sc.nextInt();
    sc.nextLine(); // consume newline

    // Initialize distSafe
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            distSafe[i][j] = 10000;
        }
    }

    // Read first grid
    for (int i = 1; i <= n; i++) {
        String line = sc.nextLine();
        for (int j = 1; j <= n; j++) {
            firstGrid[i][j] = line.charAt(j - 1);
            if (firstGrid[i][j] == 'Z') {
                q.add(new int[]{i, j});
                distSafe[i][j] = 0;
            }
            if (firstGrid[i][j] <= '9') {
                addEdge(SOURCE, (i - 1) * n + j, firstGrid[i][j] - '0');
            }
        }
    }

    // BFS from 'Z' cells
    Queue<int[]> q = new LinkedList<>();
    while (!q.isEmpty()) {
        int[] cur = q.poll();
        int x = cur[0], y = cur[1];
        for (int d = 0; d < 4; d++) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (nx >= 1 && ny >= 1 && nx <= n && ny <= n && firstGrid[nx][ny] <= '9' && distSafe[nx][ny] > distSafe[x][y] + 1) {
                distSafe[nx][ny] = distSafe[x][y] + 1;
                q.add(new int[]{nx, ny});
            }
        }
    }

    // For each digit cell in first grid, BFS to compute distances
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (firstGrid[i][j] > '9') continue;
            // Initialize distBetween for this source
            for (int k = 1; k <= n; k++) {
                for (int l = 1; l <= n; l++) {
                    distBetween[i][j][k][l] = 10000;
                }
            }
            q.add(new int[]{i, j});
            distBetween[i][j][i][j] = 0;
            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int x = cur[0], y = cur[1];
                for (int d = 0; d < 4; d++) {
                    int nx = x + dirX[d], ny = y + dirY[d];
                    if (nx >= 1 && ny >= 1 && nx <= n && ny <= n && firstGrid[nx][ny] <= '9' &&
                        distBetween[i][j][nx][ny] > distBetween[i][j][x][y] + 1 &&
                        distBetween[i][j][x][y] < distSafe[x][y]) {
                        distBetween[i][j][nx][ny] = distBetween[i][j][x][y] + 1;
                        q.add(new int[]{nx, ny});
                    }
                }
            }
            // Add edges based on distances
            for (int k = 1; k <= n; k++) {
                for (int l = 1; l <= n; l++) {
                    if (distBetween[i][j][k][l] <= Math.min(distSafe[k][l], limit)) {
                        addEdge((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
                    }
                }
            }
        }
    }

    // Read second grid
    for (int i = 1; i <= n; i++) {
        String line = sc.nextLine();
        for (int j = 1; j <= n; j++) {
            secondGrid[i][j] = line.charAt(j - 1);
            if (secondGrid[i][j] <= '9') {
                addEdge((i - 1) * n + j + 100, SINK, secondGrid[i][j] - '0');
            }
        }
    }

    runDinic();
    System.out.println(answer);
    sc.close();
}
}
